mapper.select:
SELECT sel.id, sel.student_id, sel.course_id, sel.semester_id, sel.select_time, sel.drop_time, sel.status, sel.score, sel.select_type, sel.create_time, sel.update_time, c.course_code AS courseCode, c.course_name AS courseName, c.credit AS credit, c.course_type AS courseType, tu.real_name AS teacherName FROM course_selection sel INNER JOIN course c ON c.id = sel.course_id AND c.deleted = 0 LEFT JOIN teacher t ON t.id = c.teacher_id AND t.deleted = 0 LEFT JOIN sys_user tu ON tu.id = t.user_id AND tu.deleted = 0 WHERE sel.deleted = 0 AND sel.student_id = #{studentId}
AND sel.semester_id = #{semesterId}
AND sel.status = #{status}
ORDER BY sel.select_time DESC

SELECT sel.id, sel.student_id, sel.course_id, sel.semester_id, sel.select_time, sel.status, sel.score, c.course_code AS courseCode, c.course_name AS courseName, c.credit AS credit, su.real_name AS studentName, st.stu_no AS stuNo, st.class_name AS className FROM course_selection sel INNER JOIN course c ON c.id = sel.course_id AND c.deleted = 0 INNER JOIN student st ON st.id = sel.student_id AND st.deleted = 0 INNER JOIN sys_user su ON su.id = st.user_id AND su.deleted = 0 WHERE sel.deleted = 0 AND sel.course_id = #{courseId}
AND (su.real_name LIKE CONCAT('%', #{keyword}, '%') OR st.stu_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY st.stu_no ASC

SELECT sel.course_id
FROM course_selection sel
WHERE sel.deleted = 0
AND sel.student_id = #{studentId}
AND sel.semester_id = #{semesterId}
AND sel.status = 1
